final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Scheduled workflow using EventBridge and AWS Step Functions Express State Machine
  to automatically close AWS Organizations accounts tagged with 'organizations:account-closure'='REQUESTED'
  and tag them as 'ACKNOWLEDGED'.

Resources:
  StateMachineLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/vendedlogs/states/organizations-account-closure-sm-logs
      RetentionInDays: 365

  StepFunctionsExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: OrganizationsAccountClosurePolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - organizations:ListAccounts
                  - organizations:ListTagsForResource
                  - organizations:DescribeAccount
                  - organizations:CloseAccount
                  - organizations:TagResource
                Resource: '*'
        - PolicyName: CloudWatchLogsDeliveryPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogDelivery
                  - logs:GetLogDelivery
                  - logs:UpdateLogDelivery
                  - logs:DeleteLogDelivery
                  - logs:ListLogDeliveries
                  - logs:PutLogEvents
                  - logs:PutResourcePolicy
                  - logs:DescribeResourcePolicies
                  - logs:DescribeLogGroups
                Resource: '*'

  EventBridgeRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: events.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: EventBridgeInvokeStateMachinePolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - states:StartExecution
                  - states:StartSyncExecution
                Resource: !Ref AccountClosureStateMachine

  AccountClosureStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineType: EXPRESS
      RoleArn: !GetAtt StepFunctionsExecutionRole.Arn
      LoggingConfiguration:
        Level: ALL
        IncludeExecutionData: true
        Destinations:
          - CloudWatchLogsLogGroup:
              LogGroupArn: !GetAtt StateMachineLogGroup.Arn
      DefinitionString: !Sub |
        {
          "Comment": "Process and close AWS Organization accounts tagged for closure",
          "QueryLanguage": "JSONata",
          "StartAt": "ListAccounts",
          "States": {
            "ListAccounts": {
              "Type": "Task",
              "Arguments": {
                "NextToken": "{% $states.input.NextToken %}"
              },
              "Resource": "arn:aws:states:::aws-sdk:organizations:listAccounts",
              "Output": {
                "ListAccountsResult": "{% $states.result %}",
                "NextToken": "{% $states.input.NextToken %}"
              },
              "Retry": [
                {
                  "ErrorEquals": [
                    "Organizations.TooManyRequestsException",
                    "Organizations.ConcurrentModificationException",
                    "Organizations.AWSOrganizationsNotInUseException"
                  ],
                  "IntervalSeconds": 2,
                  "MaxAttempts": 5,
                  "BackoffRate": 2.0
                }
              ],
              "Next": "ProcessAccounts"
            },
            "ProcessAccounts": {
              "Type": "Map",
              "Items": "{% $states.input.ListAccountsResult.Accounts %}",
              "ItemProcessor": {
                "ProcessorConfig": {
                  "Mode": "INLINE"
                },
                "StartAt": "ListTagsForResource",
                "States": {
                  "ListTagsForResource": {
                    "Type": "Task",
                    "Arguments": {
                      "ResourceId": "{% $states.input.Id %}"
                    },
                    "Resource": "arn:aws:states:::aws-sdk:organizations:listTagsForResource",
                    "Output": {
                      "Account": "{% $states.input %}",
                      "Tags": "{% $states.result.Tags %}"
                    },
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.TooManyRequestsException",
                          "Organizations.ConcurrentModificationException"
                        ],
                        "IntervalSeconds": 2,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Next": "IsClosureRequested"
                  },
                  "IsClosureRequested": {
                    "Type": "Choice",
                    "Choices": [
                      {
                        "Condition": "{% $exists($states.input.Tags[Key='organizations:account-closure' and Value='REQUESTED']) %}",
                        "Next": "DescribeAccount"
                      }
                    ],
                    "Default": "SkipAccount"
                  },
                  "DescribeAccount": {
                    "Type": "Task",
                    "Arguments": {
                      "AccountId": "{% $states.input.Account.Id %}"
                    },
                    "Resource": "arn:aws:states:::aws-sdk:organizations:describeAccount",
                    "Output": {
                      "Account": "{% $states.input.Account %}",
                      "AccountDetail": "{% $states.result.Account %}"
                    },
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.TooManyRequestsException",
                          "Organizations.ConcurrentModificationException"
                        ],
                        "IntervalSeconds": 2,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Next": "IsAccountActive"
                  },
                  "IsAccountActive": {
                    "Type": "Choice",
                    "Choices": [
                      {
                        "Condition": "{% $states.input.AccountDetail.Status = 'ACTIVE' %}",
                        "Next": "CloseAccount"
                      }
                    ],
                    "Default": "SkipAccount"
                  },
                  "CloseAccount": {
                    "Type": "Task",
                    "Arguments": {
                      "AccountId": "{% $states.input.Account.Id %}"
                    },
                    "Resource": "arn:aws:states:::aws-sdk:organizations:closeAccount",
                    "Output": {
                      "Account": "{% $states.input.Account %}"
                    },
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.TooManyRequestsException",
                          "Organizations.ConcurrentModificationException",
                          "Organizations.ConstraintViolationException"
                        ],
                        "IntervalSeconds": 5,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "Next": "SkipAccount"
                      }
                    ],
                    "Next": "TagAccountAcknowledged"
                  },
                  "TagAccountAcknowledged": {
                    "Type": "Task",
                    "Arguments": {
                      "ResourceId": "{% $states.input.Account.Id %}",
                      "Tags": [
                        {
                          "Key": "organizations:account-closure",
                          "Value": "ACKNOWLEDGED"
                        }
                      ]
                    },
                    "Resource": "arn:aws:states:::aws-sdk:organizations:tagResource",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.TooManyRequestsException",
                          "Organizations.ConcurrentModificationException"
                        ],
                        "IntervalSeconds": 2,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Next": "Done"
                  },
                  "SkipAccount": {
                    "Type": "Pass",
                    "End": true
                  },
                  "Done": {
                    "Type": "Pass",
                    "End": true
                  }
                }
              },
              "Output": {
                "NextToken": "{% $states.input.ListAccountsResult.NextToken %}"
              },
              "Next": "HasMoreAccounts"
            },
            "HasMoreAccounts": {
              "Type": "Choice",
              "Choices": [
                {
                  "Condition": "{% $exists($states.input.NextToken) and $states.input.NextToken != null %}",
                  "Next": "SetNextToken"
                }
              ],
              "Default": "WorkflowComplete"
            },
            "SetNextToken": {
              "Type": "Pass",
              "Output": {
                "NextToken": "{% $states.input.NextToken %}"
              },
              "Next": "ListAccounts"
            },
            "WorkflowComplete": {
              "Type": "Pass",
              "End": true
            }
          }
        }

  HourlyScheduleRule:
    Type: AWS::Events::Rule
    Properties:
      Name: hourly-account-closure-schedule
      Description: Triggers the account closure Step Functions Express state machine every hour.
      ScheduleExpression: rate(1 hour)
      State: ENABLED
      Targets:
        - Id: AccountClosureStateMachineTarget
          Arn: !Ref AccountClosureStateMachine
          RoleArn: !GetAtt EventBridgeRole.Arn

Outputs:
  StateMachineArn:
    Description: ARN of the Step Functions Express State Machine.
    Value: !Ref AccountClosureStateMachine

  EventBridgeRuleArn:
    Description: ARN of the EventBridge Scheduled Rule.
    Value: !GetAtt HourlyScheduleRule.Arn

  LogGroupArn:
    Description: ARN of the CloudWatch Log Group for State Machine Execution Logs.
    Value: !GetAtt StateMachineLogGroup.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Amazon Verified Permissions Policy Store with Cedar schema, static policies,
  and SSM parameter export for a Bookstore application.

Resources:
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: !Sub |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": ["Role"],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "years-as-member": {
                        "type": "Long",
                        "required": true
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": ["User"],
                    "resourceTypes": ["Book"],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  AdminViewAllBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: >-
            permit (
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  ForbidSpecificAdminPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: >-
            forbid (
              principal == Bookstore::User::"blocked-admin",
              action == Bookstore::Action::"View",
              resource
            );

  PublisherViewOwnedBooksPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: >-
            permit (
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              principal == resource.owner
            };

  SpecialUserViewSpecialBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: >-
            permit (
              principal == Bookstore::User::"special-user",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"special-book"
            );

  CustomerViewPremiumOffersPermitPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: >-
            permit (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal["years-as-member"] >= 2
            };

  CustomerViewPremiumOffersForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: >-
            forbid (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal["years-as-member"] < 2
            };

  ForbidNonUSRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !GetAtt BookstorePolicyStore.PolicyStoreId
      Definition:
        Static:
          Statement: >-
            forbid (
              principal,
              action in [Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers"],
              resource
            )
            unless {
              context.region == "US"
            };

  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: /bookstore/verified-permissions/policy-store-id
      Type: String
      Value: !GetAtt BookstorePolicyStore.PolicyStoreId
      Description: The Policy Store ID for the Bookstore Amazon Verified Permissions store

Outputs:
  PolicyStoreId:
    Description: The ID of the created Verified Permissions Policy Store
    Value: !GetAtt BookstorePolicyStore.PolicyStoreId
    Export:
      Name: !Sub '${AWS::StackName}-PolicyStoreId'
  SSMParameterName:
    Description: The SSM Parameter path storing the Policy Store ID
    Value: !Ref PolicyStoreIdParameter
    Export:
      Name: !Sub '${AWS::StackName}-SSMParameterName'

AWSTemplateFormatVersion: '2010-09-09'
Description: CloudFormation template for a Step Functions calculator demo with a Node.js Lambda function.

Resources:
  CalculatorLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: /aws/lambda/Calculator
      RetentionInDays: 3

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: LambdaLoggingPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: !GetAtt CalculatorLogGroup.Arn

  CalculatorFunction:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: Calculator
      Runtime: nodejs22.x
      Role: !GetAtt LambdaExecutionRole.Arn
      Handler: index.handler
      Code:
        ZipFile: |
          exports.handler = async (event) => {
            const { operator, operands } = event;
            if (!Array.isArray(operands) || operands.length < 2) {
              throw new Error("Operands must be an array with at least 2 numbers");
            }
            const [a, b] = operands;
            let result;
            switch (operator) {
              case 'add':
                result = a + b;
                break;
              case 'subtract':
                result = a - b;
                break;
              case 'multiply':
                result = a * b;
                break;
              case 'divide':
                if (b === 0) throw new Error("Division by zero");
                result = a / b;
                break;
              default:
                throw new Error(`Unsupported operator: ${operator}`);
            }
            return { result };
          };

  StateMachineExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: InvokeLambdaPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action: lambda:InvokeFunction
                Resource: !GetAtt CalculatorFunction.Arn

  CalculatorStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      RoleArn: !GetAtt StateMachineExecutionRole.Arn
      DefinitionString: !Sub |
        {
          "Comment": "Calculator State Machine with Choice routing",
          "StartAt": "CheckOperator",
          "States": {
            "CheckOperator": {
              "Type": "Choice",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "InvokeCalculator"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "subtract",
                  "Next": "InvokeCalculator"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "multiply",
                  "Next": "InvokeCalculator"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "divide",
                  "Next": "InvokeCalculator"
                }
              ],
              "Default": "UnsupportedOperator"
            },
            "InvokeCalculator": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "Parameters": {
                "FunctionName": "${CalculatorFunction.Arn}",
                "Payload.$": "$"
              },
              "OutputPath": "$.Payload",
              "End": true
            },
            "UnsupportedOperator": {
              "Type": "Fail",
              "Error": "UnsupportedOperatorError",
              "Cause": "The provided operator is not supported. Supported operators are: add, subtract, multiply, divide."
            }
          }
        }

Outputs:
  StateMachineArn:
    Description: ARN of the Calculator State Machine
    Value: !Ref CalculatorStateMachine

  SampleInputPayload:
    Description: Sample input format for testing the State Machine
    Value: '{"operator": "add", "operands": [1, 2]}'

AWSTemplateFormatVersion: '2010-09-09'
Description: Self-contained AWS AppSync GraphQL API (TodoAPIwithJs) with DynamoDB, GSI, API Key auth, JavaScript pipeline resolvers, and real-time subscriptions.

Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: OwnerIndex
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncDynamoDBPolicy
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub "${TodoTable.Arn}/index/*"

  TodoApi:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY

  TodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoApi.ApiId

  TodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Definition: |
        type Todo {
          id: ID!
          title: String!
          description: String
          owner: String!
          completed: Boolean
          createdAt: String
          updatedAt: String
        }

        input CreateTodoInput {
          title: String!
          description: String
          owner: String!
          completed: Boolean
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          owner: String
          completed: Boolean
        }

        input DeleteTodoInput {
          id: ID!
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: TodoDynamoDBDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: CreateTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { input } = ctx.args;
          const now = util.time.nowISO8601();
          const id = util.autoId();
          const item = {
            id,
            completed: false,
            createdAt: now,
            updatedAt: now,
            ...input,
          };
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: GetTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: UpdateTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { id, ...input } = ctx.args.input;
          input.updatedAt = util.time.nowISO8601();

          const sets = [];
          const removes = [];
          const expressionNames = {};
          const expressionValues = {};

          for (const [key, value] of Object.entries(input)) {
            if (value !== undefined) {
              sets.push(`#${key} = :${key}`);
              expressionNames[`#${key}`] = key;
              expressionValues[`:${key}`] = value;
            }
          }

          let updateExpression = '';
          if (sets.length > 0) {
            updateExpression += `SET ${sets.join(', ')}`;
          }

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression: updateExpression,
              expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: DeleteTodoFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.input.id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoApi.ApiId
      Name: ListTodosFunction
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const { limit = 20, nextToken } = ctx.args;
          return {
            operation: 'Scan',
            limit,
            nextToken,
